export type MotionSurface =
  | "immersive"
  | "scroll"
  | "fixed"
  | "editor"
  /** The landing runs its own scroll choreography and positions a fixed 3D
   *  object inside the route, so the shared controller must keep its hands
   *  off entirely: a route tween would leave a `filter` on the route root,
   *  which silently turns it into the containing block for every fixed
   *  descendant and drags the floating book along with the scroll. */
  | "landing";

export const MOTION_SELECTORS = {
  root: "[data-motion-root]",
  enter: "[data-motion='enter']",
  stagger: "[data-motion='stagger']",
  parallax: "[data-motion='parallax']",
  pageTurn: "[data-motion='page-turn']",
} as const;

export function getMotionSurface(pathname: string): MotionSurface {
  // Normalise before classifying. The router resolves more than one spelling
  // to the same route — a doubled slash, a trailing slash — and every surface
  // below is a claim about what the route contains, not about how its URL was
  // typed. Classifying the raw string means "//" reaches the landing while
  // being told it is a "scroll" page, and "scroll" is the answer that lets the
  // shared controller leave its filter on the route root. That filter is the
  // containing block this whole type exists to avoid: the landing's pinned
  // book, and the room's own fixed furniture, get dragged along with the
  // scroll. Same for "/shelf/" — the room, classified as a text page.
  const path = pathname.replace(/\/{2,}/g, "/").replace(/\/+$/, "") || "/";

  if (path === "/") {
    return "landing";
  }

  if (path === "/shelf" || path.startsWith("/inkverse/")) {
    return "immersive";
  }

  if (path.startsWith("/write/")) {
    return "editor";
  }

  if (path.startsWith("/practice")) {
    return "fixed";
  }

  return "scroll";
}

export function shouldShowAmbientBackdrop(surface: MotionSurface) {
  return surface !== "immersive" && surface !== "landing";
}

export function shouldAnimateRoute(surface: MotionSurface) {
  return surface !== "immersive" && surface !== "landing";
}

/** Routes whose whole viewport belongs to the room, so page chrome (the dock
 *  rail, the shelf's own menu button) either owns the screen or stays out. */
export function isRoomRoute(pathname: string) {
  return pathname === "/shelf" || pathname === "/study";
}
