import {
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
  useEffect,
  useRef,
} from "react";
import { cn } from "../../../../lib/cn";
import { usePrefersReducedMotion } from "../../../../motion/usePrefersReducedMotion";

interface Spark {
  x: number;
  y: number;
  angle: number;
  startTime: number;
}

export interface ClickSparkProps extends HTMLAttributes<HTMLDivElement> {
  sparkColor?: string;
  sparkSize?: number;
  sparkRadius?: number;
  sparkCount?: number;
  duration?: number;
  easing?: "linear" | "ease-in" | "ease-out" | "ease-in-out";
  extraScale?: number;
  disabled?: boolean;
  children?: ReactNode;
}

export function shouldRunSparkLoop(sparkCount: number) {
  return sparkCount > 0;
}

function applyEasing(value: number, easing: ClickSparkProps["easing"]) {
  switch (easing) {
    case "linear":
      return value;
    case "ease-in":
      return value * value;
    case "ease-in-out":
      return value < 0.5
        ? 2 * value * value
        : -1 + (4 - 2 * value) * value;
    default:
      return value * (2 - value);
  }
}

export default function ClickSpark({
  sparkColor = "var(--iris)",
  sparkSize = 9,
  sparkRadius = 17,
  sparkCount = 8,
  duration = 460,
  easing = "ease-out",
  extraScale = 1,
  disabled = false,
  children,
  className,
  ...props
}: ClickSparkProps) {
  const hostRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const frameRef = useRef(0);
  const sparksRef = useRef<Spark[]>([]);
  const prefersReducedMotion = usePrefersReducedMotion();
  const enabled = !disabled && !prefersReducedMotion;

  useEffect(() => {
    const host = hostRef.current;
    const canvas = canvasRef.current;
    if (!host || !canvas) return undefined;
    const context = canvas.getContext("2d");
    if (!context) return undefined;

    let dpr = 1;
    const resize = () => {
      const rect = host.getBoundingClientRect();
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(rect.width * dpr));
      canvas.height = Math.max(1, Math.round(rect.height * dpr));
      context.setTransform(dpr, 0, 0, dpr, 0, 0);
    };

    const draw = (timestamp: number) => {
      const rect = host.getBoundingClientRect();
      context.clearRect(0, 0, rect.width, rect.height);
      context.strokeStyle =
        getComputedStyle(host)
          .getPropertyValue("--motion-spark-color")
          .trim() || sparkColor;
      context.lineWidth = 2;
      context.lineCap = "round";
      sparksRef.current = sparksRef.current.filter((spark) => {
        const elapsed = timestamp - spark.startTime;
        if (elapsed >= duration) return false;

        const eased = applyEasing(elapsed / duration, easing);
        const distance = eased * sparkRadius * extraScale;
        const lineLength = sparkSize * (1 - eased);
        const x1 = spark.x + distance * Math.cos(spark.angle);
        const y1 = spark.y + distance * Math.sin(spark.angle);
        const x2 = spark.x + (distance + lineLength) * Math.cos(spark.angle);
        const y2 = spark.y + (distance + lineLength) * Math.sin(spark.angle);

        context.beginPath();
        context.moveTo(x1, y1);
        context.lineTo(x2, y2);
        context.stroke();
        return true;
      });

      if (shouldRunSparkLoop(sparksRef.current.length)) {
        frameRef.current = requestAnimationFrame(draw);
      } else {
        frameRef.current = 0;
      }
    };

    const onClick = (event: MouseEvent) => {
      if (!enabled) return;
      const rect = canvas.getBoundingClientRect();
      const now = performance.now();
      const x = event.clientX - rect.left;
      const y = event.clientY - rect.top;
      sparksRef.current.push(
        ...Array.from({ length: sparkCount }, (_, index) => ({
          x,
          y,
          angle: (2 * Math.PI * index) / sparkCount,
          startTime: now,
        })),
      );
      if (!frameRef.current) {
        frameRef.current = requestAnimationFrame(draw);
      }
    };

    resize();
    const observer = new ResizeObserver(resize);
    observer.observe(host);
    host.addEventListener("click", onClick);

    return () => {
      observer.disconnect();
      host.removeEventListener("click", onClick);
      if (frameRef.current) cancelAnimationFrame(frameRef.current);
      frameRef.current = 0;
      sparksRef.current = [];
    };
  }, [duration, easing, enabled, extraScale, sparkColor, sparkCount, sparkRadius, sparkSize]);

  return (
    <div
      {...props}
      ref={hostRef}
      className={cn("click-spark", className)}
      style={{ "--motion-spark-color": sparkColor } as CSSProperties}
    >
      <canvas ref={canvasRef} className="click-spark__canvas" aria-hidden="true" />
      {children}
    </div>
  );
}
